import 'package:agent_core/agent_core.dart';

import 'electronics_api.dart';

/// ngspice analyses offered by the screen.
enum Analysis {
  op('Ponto de operação', 'multímetro: tensão em cada rede e corrente em cada fonte'),
  tran('Transiente', 'osciloscópio: sinais no tempo'),
  ac('Resposta em frequência (AC)', 'ganho por frequência, escala logarítmica'),
  dc('Varredura DC', 'varia uma fonte e mede o circuito');

  const Analysis(this.name, this.hint);
  final String name, hint;
}

/// SPICE netlist generated by the server, what was left out (with the warnings) and the sources that can be swept.
class Spice {
  const Spice({required this.text, required this.ignored, required this.sources});

  final String text;
  final List<String> ignored;
  final List<String> sources;

  factory Spice.fromJson(Map<String, dynamic> j) => Spice(
    text: j['texto'] as String? ?? '',
    ignored: [
      for (final i in j['ignorados'] as List? ?? []) i is Map ? '${i['ref']}: ${i['motivo']}' : '$i',
      for (final a in j['avisos'] as List? ?? []) a is Map ? '${a['mensagem'] ?? a}' : '$a',
    ],
    sources: [for (final f in j['fontes'] as List? ?? []) '$f'],
  );
}

sealed class SimulationResult {
  const SimulationResult();

  factory SimulationResult.fromJson(Map<String, dynamic> j) {
    if (j['analise'] == 'op') {
      Map<String, double> mapping(Object? m) => {
        for (final e in (m as Map? ?? {}).entries) '${e.key}': (e.value as num).toDouble(),
      };
      return OperatingPoint(voltages: mapping(j['tensoes']), currents: mapping(j['correntes']));
    }
    final axis = j['eixo'] as Map<String, dynamic>;
    List<double> items(Object? l) => [for (final v in l as List) (v as num).toDouble()];
    return SimCurves(
      analysis: Analysis.values.byName(j['analise'] as String),
      axisName: axis['nome'] as String? ?? '',
      axisUnit: axis['unidade'] as String? ?? '',
      axis: items(axis['valores']),
      series: {for (final e in (j['series'] as Map).entries) '${e.key}': items(e.value)},
      phases: {for (final e in (j['fases'] as Map? ?? {}).entries) '${e.key}': items(e.value)},
    );
  }
}

class OperatingPoint extends SimulationResult {
  const OperatingPoint({required this.voltages, required this.currents});

  final Map<String, double> voltages, currents;
}

class SimCurves extends SimulationResult {
  const SimCurves({
    required this.analysis,
    required this.axisName,
    required this.axisUnit,
    required this.axis,
    required this.series,
    this.phases = const {},
  });

  final Analysis analysis;
  final String axisName, axisUnit;
  final List<double> axis;
  final Map<String, List<double>> series;
  final Map<String, List<double>> phases;

  /// `v(...)` is voltage (V), `i(...)` current (A); each quantity goes in one chart (never two y axes).
  static String unitOf(String series) => series.toLowerCase().startsWith('i(') ? 'A' : 'V';
}

extension SimulationApi on ElectronicsApi {
  Future<Spice> spice(String project) async =>
      Spice.fromJson(await cliente.get('api/eletronica/projetos/$project/spice') as Map<String, dynamic>);

  /// Requests the simulation and polls the task every second until it is ready (or [cancelled]).
  Future<SimulationResult> simulate(
    String project,
    Map<String, dynamic> request, {
    bool Function()? cancelled,
    void Function(String state)? aoMudar,
  }) async {
    final t = await cliente.post('api/eletronica/projetos/$project/simular', request) as Map<String, dynamic>;
    final limit = DateTime.now().add(const Duration(minutes: 3));
    while (true) {
      await Future<void>.delayed(const Duration(seconds: 1));
      if (cancelled?.call() ?? false) throw ApiErro(0, 'Cancelada.');
      if (DateTime.now().isAfter(limit)) throw ApiErro(0, 'A simulação passou de 3 minutos.');
      final r = await cliente.get('api/eletronica/simulacoes/${t['id']}') as Map<String, dynamic>;
      aoMudar?.call('${r['estado']}');
      if (r['estado'] == 'pronto') return SimulationResult.fromJson(r['resultado'] as Map<String, dynamic>);
      if (r['estado'] == 'erro') throw ApiErro(422, '${r['erro'] ?? 'falhou'}');
    }
  }
}
